import argparse
import json
from datetime import datetime
from pathlib import Path
root=Path(__file__).resolve().parents[2]
parser=argparse.ArgumentParser(description='Build the document threshold and generation review viewer')
parser.add_argument('--run-dir', type=Path, required=True)
parser.add_argument('--site-directory', type=Path, help='Optional hosting project; otherwise write only RUN_DIR/viewer.html')
args=parser.parse_args()
run=args.run_dir

manifest=json.loads((run/'manifest.json').read_text()) if (run/'manifest.json').exists() else {}
run_date=datetime.fromisoformat(manifest['started_at']).strftime('%d %B %Y').lstrip('0') if manifest.get('started_at') else 'Saved run'
run_model=manifest.get('model','Unspecified model')
cases=json.loads((run/'classifier_inputs.json').read_text()); preds=json.loads((run/'predictions_by_query.json').read_text()); checks=json.loads((run/'threshold_checks.json').read_text())
review_file=run/'gold_label_reviews_adjudicated.json'
if not review_file.exists():
    review_file=run/'gold_label_reviews.json'
gold_reviews=json.loads(review_file.read_text()) if review_file.exists() else {}
data=[dict(case=c,prediction=preds[c['case_id']],checks=checks[c['case_id']],
           gold_review=gold_reviews.get(c['case_id'])) for c in cases]
generation_count=sum(any(int(code[1:])>=9 for code in p.get('supported_failures',[])) for p in preds.values())
supported_gold=sum(r.get('verdict')=='supported' for r in gold_reviews.values())
questionable_gold=sum(r.get('verdict')=='questionable' for r in gold_reviews.values())
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RAG · Failure Review</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#24332e;background:#f5f6f2;font-size:14px}*{box-sizing:border-box}body{margin:0}header{padding:26px 36px;background:#163e33;color:white;display:flex;justify-content:space-between;align-items:center}h1{font-size:23px;margin:5px 0}header small{color:#bdd1c7}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase}.tag{display:inline-block;font-size:12px;padding:5px 9px;border-radius:5px;background:#e7eee9;color:#284f40;margin:2px}.warn{background:#fff0d3;color:#8a510b}.bad{background:#fbe1dc;color:#9c3628}.muted{color:#78827d}main{max-width:1500px;margin:auto;padding:24px 30px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel{background:white;border:1px solid #dfe5de;border-radius:10px;padding:20px}.stat strong{display:block;font-size:28px;margin-top:9px}.notice{padding:15px 18px;border-left:3px solid #d5a24d;background:#fff6e6;margin:20px 0;line-height:1.6}.layout{display:grid;grid-template-columns:285px minmax(0,1fr);gap:22px;margin-top:22px}aside{align-self:start;position:sticky;top:20px}input,select,button{font:inherit}input,select{padding:11px;border:1px solid #d7dfd6;border-radius:6px;width:100%;margin-bottom:9px;background:white}.case{width:100%;text-align:left;padding:14px;border:1px solid #e1e6de;background:white;border-radius:7px;cursor:pointer;margin-bottom:7px}.case.active{border-color:#28745b;background:#ebf3ed;box-shadow:inset 3px 0 #28745b}.case p{margin:7px 0 0;font-size:12px;line-height:1.5;color:#637269}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:15px}.toolbar button{padding:8px 13px;border:1px solid #cad6cc;background:white;border-radius:6px;cursor:pointer}h2{font-size:20px;margin:8px 0 17px}h3{font-size:15px;margin:0 0 12px}p{line-height:1.65}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel{margin-bottom:15px}.answer{white-space:pre-wrap;line-height:1.7;font-size:13px;overflow-wrap:anywhere}.tabs{display:flex;gap:5px;border-bottom:1px solid #d7dfd6;margin:20px 0 15px;overflow:auto}.tabs button{padding:12px 15px;background:transparent;border:0;cursor:pointer;white-space:nowrap;color:#62726a}.tabs button.active{color:#1a5c45;border-bottom:3px solid #1a5c45;font-weight:650}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:12px 9px;border-bottom:1px solid #e6ebe3;vertical-align:top}th{font-size:11px;text-transform:uppercase;color:#758176;letter-spacing:.5px}details{margin:10px 0;border:1px solid #dfe6dc;background:white;border-radius:6px;padding:13px}summary{cursor:pointer;line-height:1.6}.chunk{white-space:pre-wrap;font-size:13px;line-height:1.7;margin-top:13px;overflow-wrap:anywhere}.rank{display:inline-block;color:#87978b;margin-right:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.6}.rule{font-size:12px;color:#718176;line-height:1.6}.empty{padding:25px;color:#748176}footer{padding:25px;text-align:center;color:#849086;font-size:12px}@media(max-width:850px){header{padding:20px}main{padding:16px}.layout{grid-template-columns:1fr}aside{position:static}.cases{max-height:240px;overflow:auto}.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style><header><div><div class="eyebrow">Research workspace / Evaluation</div><h1>RAG Failure Review</h1><small>__TOTAL__ conversations · __MODEL__ · __RUN_DATE__ · Updated E9 definition</small></div><span>Document threshold pilot</span></header><main><div class="stats"><div class="stat">Completed conversations<strong>__COMPLETED__ / __TOTAL__</strong></div><div class="stat">Gold labels supported<strong>__SUPPORTED_GOLD__</strong></div><div class="stat">Gold labels questionable<strong>__QUESTIONABLE_GOLD__</strong></div><div class="stat">Cases with generation findings<strong>__GENERATION_COUNT__</strong></div></div><div class="notice"><b>Generation review and pipeline checks are independent.</b> Each case has one gold document, so the requirement for two distinct gold documents in the top three cannot be met. E4/E7/E8 are computed automatically. Generation findings and the causal primary are shown separately. Saved evidence is reconstructed; it is not a confirmed historical execution log.</div><section class="panel"><h3>Gold failure vs current prediction</h3><p class="rule">Supported means the annotated failure is defensible, not that the RAG answer is correct. Review is separate from blind classification; original labels remain unchanged. Click a case to inspect reasons and passages.</p><div style="overflow:auto"><table id="comparison-table"></table></div></section><div class="layout"><aside><input id="search" aria-label="Search conversations" placeholder="Search ID or question…"><select id="filter" aria-label="Filter conversations"><option value="all">All conversations</option><option value="E4">E4 threshold failure</option><option value="E8">E8 threshold failure</option><option value="generation">Generation findings</option><option value="review">Generation needs review</option><option value="accepted">Accepted model proposals</option><option value="gold_supported">Gold label supported</option><option value="gold_questionable">Gold label questionable</option><option value="gold_insufficient_evidence">Gold review insufficient evidence</option></select><div id="cases" class="cases"></div></aside><section><div class="toolbar"><div id="case-title" class="eyebrow"></div><div><button id="previous" aria-label="Previous case">← Previous</button> <button id="next" aria-label="Next case">Next →</button> <button id="download">Download case JSON</button></div></div><div id="content"></div></section></div></main><footer>Evidence-first evaluation · Distinct document IDs · 2-pass maximum · Single-turn conversations</footer><script>
const DATA=__DATA__;
let selected=DATA[0].case.case_id,tab='overview';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pill=(v,cls='')=>`<span class="tag ${cls}">${esc(v)}</span>`;
const doc=x=>x.doc_id??String(x.chunk_id??'').replace(/_\\d+$/,'');
function visible(){let q=$('#search').value.toLowerCase(),f=$('#filter').value;return DATA.filter(x=>(x.case.case_id+' '+x.case.original_question).toLowerCase().includes(q)&&(f==='all'||(f==='accepted'?x.checks.accepted_labels.length:f==='generation'?x.checks.accepted_labels.some(c=>Number(c.slice(1))>=9):f==='review'?x.prediction.generation_review?.status==='needs_review':f.startsWith('gold_')?x.gold_review?.verdict===f.slice(5):x.checks.threshold_flags[f])))}
function sidebar(){let rows=visible();comparisonTable(rows);$('#cases').innerHTML=rows.map(x=>`<button class="case ${x.case.case_id===selected?'active':''}" data-case="${esc(x.case.case_id)}"><b>Conversation ${esc(x.case.case_id)}</b><p>${esc(x.case.original_question.slice(0,115))}${x.case.original_question.length>115?'…':''}</p><div>${x.gold_review?pill('Gold: '+x.gold_review.annotated_label):''}${x.checks.accepted_labels.filter(c=>Number(c.slice(1))>=9).map(c=>pill(c)).join('')}${Object.entries(x.checks.threshold_flags).filter(([k,v])=>v).map(([k])=>pill(k,'warn')).join('')}</div></button>`).join('')||'<div class="empty">No matching conversations.</div>';document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{selected=b.dataset.case;render()})}
function docs(items,gold,rank=false){return (items??[]).map((x,i)=>`<details><summary>${rank?`<span class="rank">#${i+1}</span>`:''}<b>${esc(x.chunk_id??x.doc_id??x.id??'Record')}</b> ${gold.has(String(doc(x)))?pill('Gold document'):pill('Other document')} ${x.score!=null?`<span class="muted">Score ${Number(x.score).toFixed(2)}</span>`:''}</summary><div class="chunk">${esc(x.text??JSON.stringify(x.text_chunks??x,null,2))}</div></details>`).join('')||'<div class="empty">No records supplied.</div>'}
function comparisonTable(rows){$('#comparison-table').innerHTML='<thead><tr><th>Case</th><th>Gold failure</th><th>Gold-label review</th><th>Model findings</th><th>Pipeline flags</th><th>Primary</th></tr></thead><tbody>'+rows.map(x=>`<tr><td><button class="case" data-case="${esc(x.case.case_id)}">${esc(x.case.case_id)}</button></td><td>${esc(x.gold_review?.annotated_label??'Not supplied')}</td><td>${pill((x.gold_review?.verdict??'not reviewed').replaceAll('_',' '),x.gold_review?.verdict==='supported'?'':x.gold_review?.verdict==='questionable'?'bad':'warn')}</td><td>${esc(x.prediction.supported_failures.join(', ')||'none')}</td><td>${esc((x.prediction.pipeline_failures??[]).join(', ')||'none')}</td><td>${esc(x.prediction.primary_failure??'unresolved')}</td></tr>`).join('')+'</tbody>'}
function goldPanel(x,expanded=false){const r=x.gold_review;if(!r)return '<div class="panel"><h3>Gold failure review</h3><p>No gold review available.</p></div>';const old=r.historical_review;return `<div class="panel"><h3>Gold failure: ${esc(r.annotated_label)}</h3>${pill(r.verdict.replaceAll('_',' '),r.verdict==='supported'?'':r.verdict==='questionable'?'bad':'warn')} ${pill(r.review_method?.startsWith('deterministic')?'Computed threshold review':'Assistant evidence review')}<p>${esc(r.reason)}</p><p><b>Suggested label:</b> ${esc(r.suggested_failure_type??'No alternative established')}</p><p class="rule">Target: the original failure label. The evaluated answer is rag_answer_final. Original annotations are unchanged; review is not independently confirmed ground truth.</p>${expanded?`<h3>Supporting / challenging evidence</h3>${(r.evidence??[]).map(e=>`<details open><summary>${esc(e.source)} · ${esc(e.item_id??'whole collection / answer')}</summary><div class="chunk">${esc(e.quote??'Scoped collection observation')}</div><p class="rule">${esc(e.observation??'')}</p></details>`).join('')}${r.computed_metrics?'<details open><summary>Computed document metrics</summary><pre>'+esc(JSON.stringify(r.computed_metrics,null,2))+'</pre></details>':''}${old?'<details><summary>Historical index5 review · earlier full response</summary><p class="notice">Historical context only; this review was not produced for the current final-answer run.</p><pre>'+esc(JSON.stringify(old,null,2))+'</pre></details>':''}${r.automated_review_before_adjudication?'<details><summary>Automated review before assistant evidence review</summary><p class="notice">Retained for audit. This automated review may confuse answer support with failure-label support; use the reviewed verdict above.</p><pre>'+esc(JSON.stringify(r.automated_review_before_adjudication,null,2))+'</pre></details>':''}<p class="rule">${esc((r.limitations??[]).join(' '))}</p>`:''}</div>`}
function overview(x){let c=x.case,p=x.prediction,k=x.checks,m=k.reranking;return goldPanel(x)+`<div class="grid"><div class="panel"><h3>Gold / reference answer</h3><div class="answer">${esc(c.gold_answer||'Not supplied')}</div></div><div class="panel"><h3>RAG answer being evaluated</h3><div class="answer">${esc(c.original_rag_answer)}</div></div></div><div class="panel"><h3>Document threshold checks</h3><table><thead><tr><th>Rule</th><th>Observed</th><th>Computed result</th><th>Pipeline emitted</th></tr></thead><tbody>${['E4','E7','E8'].map(code=>`<tr><td><b>${code}</b><div class="rule">${{E4:'All gold documents retrieved',E7:'At least 50% of retrieved gold documents lost',E8:'At least 2 distinct gold documents in top 3 of 5'}[code]}</div></td><td>${code==='E4'?`${k.coverage.retrieved_gold_document_ids.length} / ${k.coverage.gold_document_ids.length} documents`:code==='E7'?`${m.lost_gold_document_ids.length} / ${m.retrieved_gold_document_ids.length} lost`:`${m.top_k_gold_document_ids.length} gold document(s)`}</td><td>${pill(k.threshold_flags[code]===null?'Undefined':k.threshold_flags[code]?'Failure':'Pass',k.threshold_flags[code]?'warn':'')}</td><td>${pill((p.pipeline_failures??[]).includes(code)?'Yes':'No',k.threshold_flags[code]&&!(p.pipeline_failures??[]).includes(code)?'bad':'')}</td></tr>`).join('')}</tbody></table><p class="rule">Gold IDs: ${esc(k.coverage.gold_document_ids.join(', '))} · Retrieved gold IDs: ${esc(m.retrieved_gold_document_ids.join(', ')||'none')} · Lost IDs: ${esc(m.lost_gold_document_ids.join(', ')||'none')} · Top-three gold IDs: ${esc(m.top_k_gold_document_ids.join(', ')||'none')}</p></div><div class="panel"><h3>Generation review</h3>${pill(p.generation_review?.status??'missing',p.generation_review?.status==='completed'?'':'warn')} ${pill(p.generation_assessment?.answerability??'unknown')}<p>${esc(p.generation_assessment?.reason??'No structured generation review supplied.')}</p></div><div class="panel"><h3>Classifier attribution</h3>${pill(p.attribution_status,'warn')} ${pill('Primary: '+(p.primary_failure??'unresolved'))}<p>${esc(p.answer_defect?.summary??'')}</p><p class="rule">Accepted model proposals: ${esc(k.accepted_labels.join(', ')||'none')}. No accepted label does not establish that the answer is correct.</p></div>`}
function generation(x){const p=x.prediction,g=p.generation_assessment??{},review=p.generation_review??{};return `<div class="panel"><h3>Independent generation assessment ${pill(review.status??'missing',review.status==='completed'?'':'warn')}</h3>${pill('Answerability: '+(g.answerability??'unknown'))} ${pill('Response: '+(g.response_behavior??'unknown'))}<p>${esc(g.reason??'No structured assessment supplied.')}</p><p class="rule">Completed means the checklist and citation checks passed; it does not independently verify semantic correctness.</p>${review.errors?.length?'<div class="notice">'+review.errors.map(esc).join('<br>')+'</div>':''}</div><div class="panel"><h3>E9–E16 checks</h3><table><tr><th>Code</th><th>Assessment</th><th>Reason</th><th>Accepted proposal</th></tr>${Array.from({length:8},(_,i)=>'E'+(i+9)).map(code=>`<tr><td><b>${code}</b></td><td>${pill(g.checks?.[code]?.status??'missing',g.checks?.[code]?.status==='defect'?'warn':'')}</td><td>${esc(g.checks?.[code]?.reason??'Not supplied')}</td><td>${esc(p.label_assessments?.[code]?.status??'not proposed')}</td></tr>`).join('')}</table></div><div class="panel"><h3>Assessment evidence</h3>${(g.evidence??[]).map(e=>`<details><summary>${esc(e.source)} · ${esc(e.item_id??'collection / answer')}</summary><div class="chunk">${esc(e.quote??'Scoped absence observation')}</div><p class="rule">${esc(e.observation)}</p></details>`).join('')||'<p class="muted">No evidence supplied.</p>'}</div>`}
function render(){sidebar();const x=DATA.find(x=>x.case.case_id===selected),c=x.case,p=x.prediction,gold=new Set(x.checks.coverage.gold_document_ids);$('#case-title').textContent='Conversation '+selected;$('#content').innerHTML=`<h2>${esc(c.original_question)}</h2><div class="tabs">${[['overview','Overview'],['gold-review','Gold failure review'],['generation','Generation review'],['retrieval','Retrieved ('+(c.retrieved_candidates??[]).length+')'],['rerank','Reranked ('+(c.generation_context??[]).length+')'],['gold','Gold sources'],['findings','Classifier findings'],['raw','Raw data']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div><div id="tab-content"></div>`;let body=$('#tab-content');if(tab==='overview')body.innerHTML=overview(x);if(tab==='gold-review')body.innerHTML=goldPanel(x,true);if(tab==='generation')body.innerHTML=generation(x);if(tab==='retrieval')body.innerHTML='<p class="rule">Initial candidate order, before reranking. Gold membership uses document IDs.</p>'+docs(c.retrieved_candidates,gold,true);if(tab==='rerank')body.innerHTML='<p class="rule">Actual saved order. Positions 1–3 determine E8; all five determine retained documents for E7.</p>'+docs(c.generation_context,gold,true);if(tab==='gold')body.innerHTML=docs(c.source_documents,gold);if(tab==='findings')body.innerHTML=Object.entries(p.stages??{}).map(([stage,v])=>`<div class="panel"><h3>${esc(stage)} ${pill(v.status)}</h3><p>${esc(v.findings)}</p></div>`).join('')+Object.entries(p.label_assessments??{}).map(([code,v])=>`<details><summary><b>${esc(code)} ${esc(v.name)}</b> ${pill(v.status,'warn')}</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`).join('');if(tab==='raw')body.innerHTML='<details open><summary>Case, prediction and computed checks</summary><pre>'+esc(JSON.stringify(x,null,2))+'</pre></details>';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});let i=DATA.indexOf(x);$('#previous').disabled=i===0;$('#next').disabled=i===DATA.length-1}
$('#search').oninput=sidebar;$('#filter').onchange=sidebar;$('#previous').onclick=()=>{selected=DATA[Math.max(0,DATA.findIndex(x=>x.case.case_id===selected)-1)].case.case_id;render()};$('#next').onclick=()=>{selected=DATA[Math.min(DATA.length-1,DATA.findIndex(x=>x.case.case_id===selected)+1)].case.case_id;render()};$('#download').onclick=()=>{const x=DATA.find(x=>x.case.case_id===selected),url=URL.createObjectURL(new Blob([JSON.stringify(x,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='conversation-'+selected+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></html>'''
html=html.replace('__COMPLETED__',str(len(preds))).replace('__TOTAL__',str(len(cases))).replace('__SUPPORTED_GOLD__',str(supported_gold)).replace('__QUESTIONABLE_GOLD__',str(questionable_gold)).replace('__GENERATION_COUNT__',str(generation_count)).replace('__RUN_DATE__', run_date).replace('__MODEL__',run_model)
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
if args.site_directory:
    (args.site_directory/'dist').mkdir(parents=True,exist_ok=True)
    (args.site_directory/'dist/index.html').write_text(html)
(run/'viewer.html').write_text(html)
